def separate_balanced_parentheses(paren_string: str) -> List[str]:
    """Separate balanced parentheses from the input string.

    Args:
        paren_string (str): Input string containing multiple groups of nested parentheses.

    Returns:
        List[str]: A list of balanced parentheses strings.

    Raises:
        ValueError: If the input string is empty, contains unbalanced parentheses, or is not a string.
        TypeError: If the input is not a string.
    """
    if not isinstance(paren_string, str):
        raise TypeError("Input must be a string.")
    if not paren_string:
        raise ValueError("Input string is empty.")
    paren_string = re.sub(r'\s+', '', paren_string)  # Remove consecutive spaces

    result = []
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                raise ValueError("Unbalanced parentheses: ')' without matching '('")
        elif stack:
            stack.append(char)
        else:
            # If we encounter a closing parenthesis without a matching opening parenthesis,
            # start a new stack for the next group.
            stack = []
    if stack:
        raise ValueError("Unbalanced parentheses: '(' without matching ')")

    # Append the last group to the result if the string ends with a closing parenthesis.
    if stack:
        result.append(''.join(stack))

    return result

